/**
 * KS-1194 — a verification-request save that did not persist is never acknowledged (Kam: fail-closed).
 *
 * `saveVerificationRequest` set the in-memory copy, swallowed a failed INSERT with a warning and
 * returned, so POST /me/verification answered 200 PENDING for a row that did not exist, and the
 * review raised the user's level and answered "approved" while the row stayed PENDING. Now the row
 * is written first and memory set only after it lands (infrastructure → 503, anything else
 * rethrown), and approve raises the level only after the APPROVED row persists. The two writes
 * cannot share a transaction (updateUser takes no client), so a failed level update restores the
 * row to PENDING and answers 503; if the restore also fails, an error line names the request.
 *
 * Harness: the KS-1018 suite's — the real userRoutes and errorHandler, the db and userRepo mocked,
 * the real isInfrastructureDbError. The db mock keeps the verification rows it was asked to write.
 */
import { describe, it, expect, beforeAll, afterAll, beforeEach, vi } from 'vitest';
import type { AddressInfo } from 'node:net';
import type { Server } from 'node:http';
import express from 'express';

type Row = Record<string, unknown>;
const state = vi.hoisted(() => ({
  caller: { userId: 'u', role: 'USER', tenantId: 'tenant-default' } as Record<string, string>,
  users: new Map<string, Record<string, unknown>>(),
  dbAvailable: true,
  rows: new Map<string, Record<string, unknown>>(),
  insertPlan: [] as Array<'ok' | 'infra' | 'other'>,
  pendingReadFails: false,
  raise: 'ok' as 'ok' | 'null' | 'throw',
  calls: [] as string[],
}));
const INFRA = vi.hoisted(() => () => Object.assign(new Error('connect ECONNREFUSED 127.0.0.1:5432'), { code: 'ECONNREFUSED' }));
const OTHER = vi.hoisted(() => () => Object.assign(new Error('value too long for type character varying(32)'), { code: '22001' }));

const dbQuery = vi.hoisted(() => vi.fn(async (sql: string, params: unknown[] = []) => {
  if (sql.includes('INSERT INTO verification_upgrade_requests')) {
    const mode = state.insertPlan.length > 0 ? state.insertPlan.shift() : 'ok';
    state.calls.push('save:' + String(params[5]));
    if (mode === 'infra') throw INFRA();
    if (mode === 'other') throw OTHER();
    state.rows.set(String(params[0]), { id: params[0], user_id: params[1], current_level: params[2], target_level: params[3], documents: params[4], status: params[5], submitted_at: params[6], reviewed_at: params[7], reviewed_by: params[8], rejection_reason: params[9] });
    return { rows: [], rowCount: 1 };
  }
  if (sql.includes("status = 'PENDING'")) {
    if (state.pendingReadFails) throw OTHER();
    return { rows: [...state.rows.values()].filter((r) => r.user_id === params[0] && r.status === 'PENDING').slice(0, 1) };
  }
  if (sql.includes('WHERE id = $1')) return { rows: state.rows.has(String(params[0])) ? [state.rows.get(String(params[0]))] : [] };
  return { rows: [] };
}));

vi.mock('../repositories/userRepo', () => {
  const repoMock = {
    getUserById: vi.fn(async (id: string) => state.users.get(id) ?? null),
    getUserByIdPlatformScope: vi.fn(async (id: string) => state.users.get(id) ?? null),
    updateUser: vi.fn(async () => null),
    updateUserPlatformScope: vi.fn(async (id: string) => {
      state.calls.push('raise');
      if (state.raise === 'throw') throw INFRA();
      return state.raise === 'null' ? null : state.users.get(id) ?? null;
    }),
    listUsers: vi.fn(async () => []),
    countUsers: vi.fn(async () => 0),
    listOrganizations: vi.fn(async () => []),
    getOrganizationTenant: vi.fn(async () => ({ tenantId: 'tenant-default' })),
    emailExists: vi.fn(async () => false),
    createUser: vi.fn(async (user: Record<string, unknown>) => user),
    createInvitedStub: vi.fn(async () => ({ user: {}, alreadyExisted: false })),
  };
  return { default: repoMock, __esModule: true, ...repoMock };
});
vi.mock('../middleware/authenticate', () => {
  const injectCaller = () => (req: express.Request & { user?: unknown }, _res: express.Response, next: express.NextFunction) => {
    (req as { user: unknown }).user = { ...state.caller };
    next();
  };
  return { authenticate: injectCaller, authenticateAccessOrConnector: injectCaller };
});
vi.mock('../db', () => ({ isDbAvailable: () => state.dbAvailable, query: dbQuery }));
vi.mock('../services/session', () => ({ revokeAllUserSessions: vi.fn(async () => 0) }));
vi.mock('../services/password', () => ({
  hashPassword: vi.fn(async () => 'hashed'),
  checkPasswordStrength: vi.fn(() => ({ ok: true })),
  verifyPassword: vi.fn(async () => true),
}));
vi.mock('../utils/logger', () => ({ logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() } }));

import { userRoutes } from '../routes/users';
import { errorHandler } from '../middleware/errorHandler';
import { logger } from '../utils/logger';

let server: Server;
let baseUrl: string;

beforeAll(async () => {
  const app = express();
  app.use(express.json());
  app.use('/', userRoutes);
  app.use(errorHandler);
  await new Promise<void>((resolve) => {
    server = app.listen(0, '127.0.0.1', () => {
      baseUrl = 'http://127.0.0.1:' + String((server.address() as AddressInfo).port);
      resolve();
    });
  });
});
afterAll(async () => { await new Promise<void>((resolve) => server.close(() => resolve())); });

function user(id: string): void {
  state.users.set(id, { id, email: id + '@tenant.example', role: 'USER', status: 'ACTIVE', verificationLevel: 'BASIC', mfaEnabled: false, tenantId: 'tenant-default' });
}
function pendingRow(id: string, userId: string): void {
  state.rows.set(id, { id, user_id: userId, current_level: 'BASIC', target_level: 'ENHANCED', documents: [], status: 'PENDING', submitted_at: '2026-09-17T00:00:00.000Z', reviewed_at: null, reviewed_by: null, rejection_reason: null });
}
async function call(method: string, path: string, body: unknown): Promise<{ status: number; json: Row }> {
  const res = await fetch(baseUrl + path, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  return { status: res.status, json: (await res.json()) as Row };
}
const code = (json: Row): unknown => (json.error as Row | undefined)?.code;

beforeEach(() => {
  vi.clearAllMocks();
  state.users.clear();
  state.rows.clear();
  state.insertPlan = [];
  state.pendingReadFails = false;
  state.dbAvailable = true;
  state.raise = 'ok';
  state.calls = [];
});

describe('KS-1194 — POST /me/verification never acknowledges a request that did not persist', () => {
  it('🔴 a refused INSERT answers 503, and no row exists', async () => {
    user('u-submit-infra');
    state.caller = { userId: 'u-submit-infra', role: 'USER', tenantId: 'tenant-default' };
    state.insertPlan = ['infra'];
    const r = await call('POST', '/me/verification', { targetLevel: 'ENHANCED' });
    expect([r.status, code(r.json), state.rows.size]).toEqual([503, 'SERVICE_UNAVAILABLE', 0]);
  });

  it('🔴 nothing is kept in memory: after a refused INSERT, a retry (the pending read falling back to memory) creates exactly one request', async () => {
    user('u-submit-retry');
    state.caller = { userId: 'u-submit-retry', role: 'USER', tenantId: 'tenant-default' };
    state.insertPlan = ['infra'];
    await call('POST', '/me/verification', { targetLevel: 'ENHANCED' });
    state.pendingReadFails = true;
    const r = await call('POST', '/me/verification', { targetLevel: 'ENHANCED' });
    expect([r.status, (r.json.data as Row | undefined)?.status, state.rows.size]).toEqual([200, 'PENDING', 1]);
  });

  it('🔴 a non-infrastructure INSERT failure is not acknowledged either (500)', async () => {
    user('u-submit-other');
    state.caller = { userId: 'u-submit-other', role: 'USER', tenantId: 'tenant-default' };
    state.insertPlan = ['other'];
    const r = await call('POST', '/me/verification', { targetLevel: 'ENHANCED' });
    expect([r.status, state.rows.size]).toEqual([500, 0]);
  });

  it('🟢 control: with no database at all the request is still accepted in memory, as before', async () => {
    user('u-submit-nodb');
    state.caller = { userId: 'u-submit-nodb', role: 'USER', tenantId: 'tenant-default' };
    state.dbAvailable = false;
    const r = await call('POST', '/me/verification', { targetLevel: 'ENHANCED' });
    expect([r.status, (r.json.data as Row | undefined)?.status, dbQuery.mock.calls.length]).toEqual([200, 'PENDING', 0]);
  });
});

describe('KS-1194 — the review raises the level only after the row persists', () => {
  const admin = (): void => { state.caller = { userId: 'admin-1194', role: 'SYSTEM_ADMIN', tenantId: 'tenant-default' }; };

  it('🔴 approve: a refused save answers 503, the level is NOT raised, and the row stays PENDING', async () => {
    admin(); user('u-appr-savefail'); pendingRow('vr-appr-savefail', 'u-appr-savefail');
    state.insertPlan = ['infra'];
    const r = await call('POST', '/verification/vr-appr-savefail/review', { action: 'approve' });
    expect([r.status, state.calls, state.rows.get('vr-appr-savefail')?.status]).toEqual([503, ['save:APPROVED'], 'PENDING']);
  });

  it('🔴 approve: the row is saved APPROVED BEFORE the level is raised', async () => {
    admin(); user('u-appr-ok'); pendingRow('vr-appr-ok', 'u-appr-ok');
    const r = await call('POST', '/verification/vr-appr-ok/review', { action: 'approve' });
    expect([r.status, r.json.message, state.calls, state.rows.get('vr-appr-ok')?.status]).toEqual([200, 'Verification approved', ['save:APPROVED', 'raise'], 'APPROVED']);
  });

  it('🔴 approve: a level update matching no row (null) restores the row to PENDING and answers 503', async () => {
    admin(); user('u-appr-null'); pendingRow('vr-appr-null', 'u-appr-null');
    state.raise = 'null';
    const r = await call('POST', '/verification/vr-appr-null/review', { action: 'approve' });
    expect([r.status, code(r.json), state.calls, state.rows.get('vr-appr-null')?.status, state.rows.get('vr-appr-null')?.reviewed_by]).toEqual([503, 'SERVICE_UNAVAILABLE', ['save:APPROVED', 'raise', 'save:PENDING'], 'PENDING', null]);
  });

  it('🔴 approve: a level update that throws restores the row to PENDING and answers 503', async () => {
    admin(); user('u-appr-throw'); pendingRow('vr-appr-throw', 'u-appr-throw');
    state.raise = 'throw';
    const r = await call('POST', '/verification/vr-appr-throw/review', { action: 'approve' });
    expect([r.status, code(r.json), state.calls, state.rows.get('vr-appr-throw')?.status]).toEqual([503, 'SERVICE_UNAVAILABLE', ['save:APPROVED', 'raise', 'save:PENDING'], 'PENDING']);
  });

  it('🔴 approve, double failure: the level update fails, the level reads unchanged, AND the restore fails — 503, no success body, one error line naming the request', async () => {
    admin(); user('u-appr-double'); pendingRow('vr-appr-double', 'u-appr-double');
    state.raise = 'null';
    state.insertPlan = ['ok', 'infra'];
    const r = await call('POST', '/verification/vr-appr-double/review', { action: 'approve' });
    const calls = vi.mocked(logger.error).mock.calls as unknown as Array<[string, Record<string, unknown>]>;
    // KS-1194 r2 (QA F-2): the line states what was measured (the level read back as not the target), not a cause.
    const lines = calls.filter(([msg]) => msg.includes('could not be restored to PENDING; it may read APPROVED while the level does not read the target level'));
    expect([r.status, code(r.json), r.json.success, lines.length, lines[0]?.[1]?.requestId, lines[0]?.[1]?.userId, lines[0]?.[1]?.targetLevel]).toEqual([503, 'SERVICE_UNAVAILABLE', false, 1, 'vr-appr-double', 'u-appr-double', 'ENHANCED']);
  });

  it('🔴 reject: a refused save answers 503 and the row stays PENDING', async () => {
    admin(); user('u-rej-savefail'); pendingRow('vr-rej-savefail', 'u-rej-savefail');
    state.insertPlan = ['infra'];
    const r = await call('POST', '/verification/vr-rej-savefail/review', { action: 'reject', reason: 'blurry' });
    expect([r.status, state.rows.get('vr-rej-savefail')?.status]).toEqual([503, 'PENDING']);
  });

  it('🟢 control: a healthy reject answers 200, saves REJECTED and never touches the level', async () => {
    admin(); user('u-rej-ok'); pendingRow('vr-rej-ok', 'u-rej-ok');
    const r = await call('POST', '/verification/vr-rej-ok/review', { action: 'reject', reason: 'blurry' });
    expect([r.status, state.calls, state.rows.get('vr-rej-ok')?.status]).toEqual([200, ['save:REJECTED'], 'REJECTED']);
  });
});
